Script.ScriptCode:
/**
 * Calculate and store time spent on a specific code index.
 * 
 * @param {number} code - Index of the hidtime array to update.
 * 
 * This function:
 * 1. Reads the time spent on the current page (myTime)
 * 2. Adds it to the existing stored time for this code
 * 3. Converts total seconds → minutes.decimal format
 * 4. Stores both raw seconds (hidtime) and formatted minutes (Finaltime)
 */

// [WG] [DEAD CODE] - replaced by timestamp utils
function captime(code)   //Pass precode from hidtime variable for which the duration needs to be calculated
{
  // Retrieve domain labels for debugging or mapping (not used further)
  var arrTime = f("hidCheckPart").domainLabels();
  arrTime.unshift(" ");
  //[WG] [DEAD CODE] remove all response.write debugging lines
  //var mynm = String();
  //mynm = ""+arrTime[code];
  //Response.Write(Cookies);

  // Read posted time value from the form
  var myTime=Request.Form.item("myTime");
  //Response.Write("time_t1="+myTime);
  if (myTime!=null) {
    var t1 = parseInt(Request.Form.item("myTime"));
  }

  if (!f("hidtime").item(code).toBoolean()) {
    var sum = parseInt(0);
  }
  else {
    // Retrieve existing stored time for this code
    var sum = parseInt(f("hidtime").item(code).get());
  }

  if (t1==null) t1=0

  // Add new time to accumulated time
  var final = parseInt(sum+t1);

  // Store raw seconds back into hidtime
  f("hidtime").item(code).set(final);

  //Response.Write("Second : "+final+"<br>");
  // Convert seconds → minutes.decimal
  var min = parseInt(final/60);  
  var mod = parseInt(final%60);
  //Response.Write("mod : "+mod +"<br>");

  // Format seconds to always be 2 digits
  if (mod < 10) {
    var finaldata = min+".0"+mod;
  }
  else
  {
    var finaldata = min+"."+mod;
  }
  //Response.Write("LOI : "+finaldata +"<br>");
  // Store formatted time into Finaltime
  f("Finaltime").item(code).set(finaldata);

}

/**
 * captimeCheck()
 * 
 * Loops through all domain values in hidCheckPart and triggers captime(code)
 * for each value that is currently selected.
 * 
 * Also logs the posted myTime value into TestTime for debugging.
 */

function captimeCheck() {
	// Retrieve all domain values for hidCheckPart
	var arr = f("hidCheckPart").domainValues();

	// [WG] [DEAD CODE]
	// var s = Request.QueryString.item("myTime");
	// var s = Request.ServerVariables("mytime");

	// Read posted time value from form
	var s = Request.Form.item("myTime");

	// [WG] [SUGGESTION] to remove TestTime
	// Store raw time for debugging or monitoring
	f("TestTime").set("Time: "+s);

	// Loop through each domain value
	for(var i=0; i<arr.length; i++)
	{
		// Check if the current domain value is selected
        // isect(set(x)).size() > 0 means "this value is selected/set"
		if(f("hidCheckPart").isect(set(arr[i])).size() > 0)	{
			// Accumulate time for this code
			captime(arr[i]);
		}
	}
}

