    return f('incentive_amount').get();
}

// Get the survey name for history display
function PointsLabel() {
    return f('survey_name').get()
        + " (" + f('src_job_id').get() + ") completed, awarded "
        + f('incentive_amount').get() + " dollars.";
}

function AdditionalPointsLabel(amount, section) {
    return "Additional " + section
        + " (" + f('src_job_id').get() + ") completed, awarded "
        + amount + " dollars.";
}

// Debug_mode is a boolean that can be used for conditional testing. 
// It is set to 1 only when survey is accessed by a seeded panellist
if (!IsInProductionMode()) {
  var recordid = "10000001"
}
else {
  var recordid = f('recordid').get()
}

if (recordid && recordid.startsWith('1000')) {
  f('debug_mode').set(1);
} else {
  f('debug_mode').set(0);
}

/**
 * Validates other-specify bopen-end box for numeric response and set allowed range
 * *
 * @param {string} qid  - Question ID
 * @param {number} rMin - Minimum allowed value
 * @param {number} rMax - Maximum allowed value
 */
function validateOtherSpecifyNumeric(qid, rMin, rMax) {
    var val1 = parseFloat(f(qid));

    // Only validate if the question has a value
    if (f(qid).toBoolean() && (isNaN(val1) || (!isNaN(val1) && (val1 < rMin || val1 > rMax)))) {
        RaiseError();
        ClearQuestionErrorMessage();
        ClearErrorMessage();

        SetQuestionErrorMessage(LangIDs.en_au, "Invalid input. Please enter a value between " + rMin  + " and " + rMax +".");
        //[WG] [SUGGESTION] should we uncomment the line below?
        //return false;
    } else {
        return true;
    }
}

/**
 * Capture the order of selected codes for a question. Apply when a question has randomised order for statements.
 */
function captureorder(Q) 
{
    f(Q+"_order").set(f(Q).domainValues().toLocaleString());
}

/**
 * Capture the order of scale responses for a grid question. Apply when a grid question has randomised order for response codes.
 */
function captureorder_scale(Q, c) {
    f(Q + '_scale_order').set(f(Q + '_' + c).domainValues().toLocaleString());
}

/**
 * Clear all values in a question (single or multi).
 */
// [WG] [EXPLAIN] when to use this and why?
function ClearForm(form)
{
    if(form.COMPOUND)
    {
        var frmCodes = form.domainValues();
        for(var i=0;i<frmCodes.length;i++)
        {
            form.item(frmCodes[i]).set(null);
        }
    } else {
        form.set(null);
    }
}

//[WG] do we still use this way to calculate session length?
/**
 * Calculate time difference between tStart and tEnd in minutes.
 * Start time is set in hidden variable "tStart" by call block "CaptureTime" at the start of a section.
 * This function is called at the end of the section to calculate the total time taken to complete a session.
 */
function calcTimeDiff() {
    // Set session end time
    f("tEnd").set(new Date());

    var time_diff1 = 0;

    if (f("tStart").toBoolean()) {
        var vStart = new Date(f("tStart").get())
        var vEnd = new Date(f("tEnd").get())

        //Get time and convert  milliseconds to minutes
        time_diff1 = ((vEnd.getTime() - vStart.getTime()) / 60000).toFixed(3);
    }

    // Clear variables
    f("tStart").set(null);
    f("tEnd").set(null);

    return time_diff1;
}

/**
 * Update a timestamp variable qid with the calculated time difference.
 */
function updateTimestampVar(qid) {
    if (!f(qid).toBoolean()) {
        f(qid).set(calcTimeDiff());
    }
}

/**
 * Show a customised error message based on a code label in standarderrormessage variable.
 */
function errormessage(code) {
    var mesg = f("standarderrormessage").item(code).label();
    var lang = CurrentLang();

    RaiseError();
    ClearErrorMessage();
    ClearQuestionErrorMessage();
    SetQuestionErrorMessage(lang, mesg);
}
// [WG] [EXPLAIN] what's the differenct use case between these two customised error functions?
