function maskingAM_FLAG() {
    var st = set(); // Initialize an empty set
    var count = parseInt(f('AM_flag_count').get(), 10); // Convert open-end to number

    if (count === 0) {
        st = set('1', '2', '4'); //LinA only leave AM for mobile number
        //st = set('1', '2', '3');
    } else if (count === 1) {
        st = set('1', '2', '4');
    } else if (count >= 2) {
        st = set('1', '2');
    }

    return st;
}

